CREATE TABLE IF NOT EXISTS `season_premium` (`user_id` INT NOT NULL, `season_key` VARCHAR(7) NOT NULL, `bought_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`user_id`, `season_key`), CONSTRAINT `fk_season_premium_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `season_claims` (`user_id` INT NOT NULL, `season_key` VARCHAR(7) NOT NULL, `tier` TINYINT NOT NULL, `track` ENUM('free','premium') NOT NULL DEFAULT 'free', `claimed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`user_id`, `season_key`, `tier`, `track`), CONSTRAINT `fk_season_claims_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `blitz_runs` (`id` INT AUTO_INCREMENT PRIMARY KEY, `user_id` INT NOT NULL, `score` INT NOT NULL DEFAULT 0, `total` INT NOT NULL DEFAULT 0, `xp` INT NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_blitz_runs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_blitz_runs_day ON `blitz_runs` (`created_at`, `score`);
